LOGIN_PAGE = """<!doctype html><html><head><meta charset='utf-8'><meta name='viewport' content='width=device-width'>
<meta name='theme-color' content='#1262c5'><link rel='manifest' href='/manifest.webmanifest'><title>Package Tracker Login</title>
<style>body{font:16px system-ui;margin:0;background:#f5f6fa;color:#172033}main{max-width:420px;margin:64px auto;padding:20px}.card{background:#fff;padding:28px;border-radius:18px;box-shadow:0 8px 30px #17203318}h1{margin-top:0}label{display:block;margin:18px 0 7px}input{box-sizing:border-box;width:100%;padding:13px;border:1px solid #ccd2dc;border-radius:10px;font:inherit}button{width:100%;padding:13px;margin-top:18px;border:0;border-radius:10px;background:#1262c5;color:#fff;font:inherit;font-weight:600}.muted{color:#687386}.error{color:#a22525;min-height:24px}</style></head>
<body><main><div class='card'><h1>Package Tracker</h1><p class='muted'>Sign in with the WhatsApp number you use to forward shipments.</p><form id='phoneForm'><label for='phone'>WhatsApp number</label><input id='phone' type='tel' autocomplete='tel' placeholder='+1 604 555 0123' required><button>Send login code</button></form><form id='codeForm' hidden><label for='code'>Six-digit code</label><input id='code' inputmode='numeric' autocomplete='one-time-code' pattern='[0-9]{6}' maxlength='6' required><button>Open my deliveries</button></form><p class='error' id='message'></p></div></main>
<script>let phone='';const msg=document.querySelector('#message');document.querySelector('#phoneForm').onsubmit=async e=>{e.preventDefault();msg.textContent='Sending…';phone=document.querySelector('#phone').value;const r=await fetch('/api/auth/request-code',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({phone})});const d=await r.json();if(!r.ok){msg.textContent=d.detail||'Could not send code';return}e.target.hidden=true;document.querySelector('#codeForm').hidden=false;msg.textContent='Check WhatsApp for your code.'};document.querySelector('#codeForm').onsubmit=async e=>{e.preventDefault();msg.textContent='Checking…';const code=document.querySelector('#code').value;const r=await fetch('/api/auth/verify-code',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({phone,code})});const d=await r.json();if(!r.ok){msg.textContent=d.detail||'Invalid code';return}location.href='/app'};if('serviceWorker'in navigator)navigator.serviceWorker.register('/service-worker.js');</script></body></html>"""


APP_PAGE = """<!doctype html><html><head><meta charset='utf-8'><meta name='viewport' content='width=device-width'>
<meta name='theme-color' content='#1262c5'><link rel='manifest' href='/manifest.webmanifest'><title>My Deliveries</title>
<style>body{font:15px system-ui;margin:0;background:#f5f6fa;color:#172033}main{max-width:900px;margin:32px auto;padding:0 16px}header{display:flex;align-items:center;justify-content:space-between;gap:12px}h1{font-size:30px}.card{background:#fff;border-radius:16px;box-shadow:0 8px 30px #17203312;overflow:hidden}.shipment{padding:16px;border-bottom:1px solid #edf0f5}.shipment:last-child{border:0}.top{display:flex;justify-content:space-between;gap:12px}.carrier{color:#687386;text-transform:capitalize}.status{display:inline-block;margin-top:10px;padding:5px 9px;border-radius:99px;background:#e8f1ff;color:#1262c5}button{padding:9px 12px;border:1px solid #ccd2dc;border-radius:9px;background:#fff;color:#172033}a{color:#1262c5}.empty{padding:24px;color:#687386}</style></head>
<body><main><header><div><h1>My deliveries</h1><p>Packages forwarded from your WhatsApp account.</p></div><button id='logout'>Log out</button></header><div class='card' id='shipments'><div class='empty'>Loading…</div></div></main>
<script>const e=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));async function load(){const r=await fetch('/api/me/shipments');if(r.status===401){location.href='/login';return}const d=await r.json();document.querySelector('#shipments').innerHTML=d.shipments.map(x=>`<div class='shipment'><div class='top'><div><strong>${e(x.item_label)}</strong><div class='carrier'>${e(x.carrier)}</div></div><a href='${e(x.tracking_url||'#')}' target='_blank' rel='noopener noreferrer'>${e(x.tracking_number)} ↗</a></div><span class='status'>${e(x.status)}</span></div>`).join('')||`<div class='empty'>No deliveries yet. Forward a shipping message to the WhatsApp bot.</div>`}document.querySelector('#logout').onclick=async()=>{await fetch('/api/auth/logout',{method:'POST'});location.href='/login'};load();setInterval(load,15000);if('serviceWorker'in navigator)navigator.serviceWorker.register('/service-worker.js');</script></body></html>"""
